function validate([numPeople]) {
  if (!Number.isInteger(numPeople) || numPeople < 2 || numPeople > 1000) return 'numPeople is an integer from 2 to 1000.';
  if (numPeople % 2 !== 0) return 'numPeople must be even, so everyone has a partner.';
  return null;
}

