function numberOfWays(numPeople) {
  const MOD = 1000000007n;
  const pairs = numPeople / 2;
  const dp = new Array(pairs + 1).fill(0n);
  dp[0] = 1n;

  for (let i = 1; i <= pairs; i++) {
    for (let inside = 0; inside < i; inside++) {
      const outside = i - 1 - inside;
      dp[i] = (dp[i] + dp[inside] * dp[outside]) % MOD;
    }
  }
  return Number(dp[pairs]);
}

