function numberOfWays(numPeople) {
  // Closed form for the Catalan number: C(2n, n) / (n + 1), computed exactly with BigInt.
  const n = BigInt(numPeople / 2);
  let binomial = 1n;
  for (let k = 1n; k <= n; k++) binomial = binomial * (n + k) / k;
  return Number((binomial / (n + 1n)) % 1000000007n);
}

